library(shiny)

# Data + helpers ----

tooltxt <- read.csv("DecisionToolText.csv", header = TRUE, stringsAsFactors = FALSE)

# Review mode flag — set to TRUE for partner review, FALSE for production
REVIEW_MODE <- TRUE

get_txt <- function(tag) {
  idx <- which(tooltxt$TextTag == tag)
  if (length(idx) == 0) return("")
  x <- tooltxt$Text[idx[1]]
  if (REVIEW_MODE) {
    rc <- tooltxt$ReviewCode[idx[1]]
    if (!is.na(rc) && nzchar(trimws(rc))) {
      x <- paste0(x, " (", trimws(rc), ")")
    }
  }
  x
}

# Build a row of equal-width buttons (auto-sizes columns to fit count)
make_choice_buttons <- function(button_info) {
  n <- length(button_info)
  col_width <- max(3L, 12L %/% n)
  fluidRow(
    lapply(button_info, function(btn) {
      column(
        width = col_width,
        actionButton(
          inputId  = btn$id,
          label    = btn$label,
          style    = "white-space: normal; height: auto; width: 100%; margin-bottom: 10px;",
          `data-toggle` = "tooltip",
          title    = btn$tooltip
        )
      )
    })
  )
}

# UI ----

