            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/bird-monitoring-methods/' target='_blank'>Bird Monitoring Methods</a> — Overview of survey methods: point counts, transect surveys, fixed location counts, eBird, and acoustic monitoring.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/sample-bird-monitoring-protocols/' target='_blank'>Sample Bird Monitoring Protocols</a> — Customized protocol examples for a range of survey methods."))
          ),
          tags$hr(),

          h4("eBird"),
          tags$ul(
            tags$li(HTML("<a href='https://ebird.org/explore' target='_blank'>eBird Explore</a> — Browse recent bird observations by location, species, or checklist.")),
            tags$li(HTML("<a href='https://science.ebird.org/en/status-and-trends' target='_blank'>eBird Status and Trends</a> — Web interface for species abundance maps, seasonal animations, and population trend estimates.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/ebird-status-and-trends/' target='_blank'>eBird Status and Trends (Cornell Land Trust)</a> — Guidance for using S&T products in land management contexts.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/using-ebird-for-monitoring/' target='_blank'>Using eBird for Monitoring</a> — Tools and resources for incorporating eBird into a monitoring program.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/assess-and-evaluate-management/' target='_blank'>eBird for Effects Monitoring</a> — How eBird data can be used to assess bird response to management.")),
            tags$li(HTML("<a href='https://cran.r-project.org/web/packages/ebirdst/index.html' target='_blank'>ebirdst R Package</a> — R package for downloading and analyzing eBird Status and Trends raster data.")),
            tags$li(HTML("<a href='https://www.gbif.org/dataset/4fa7b334-ce0d-4e88-aaae-2e0c138d049e' target='_blank'>eBird Data on GBIF</a> — Download raw eBird observation data.")),
            tags$li(HTML("<a href='https://support.ebird.org/en/support/solutions/articles/48000907878-upload-spreadsheet-data-to-ebird' target='_blank'>eBird Bulk Data Upload</a> — Submit spreadsheet data directly to eBird."))
          ),
          tags$hr(),

          h4("Breeding Bird Atlas (BBA)"),
          tags$ul(
            tags$li("BBA resources vary by state. Search for your state name + \"Breeding Bird Atlas\" to find the most recent atlas for your region."),
            tags$li(HTML("<a href='https://www.psupress.org/books/titles/978-0-271-08980-5.html' target='_blank'>West Virginia 2nd BBA</a> — Example of a published atlas.")),
            tags$li(HTML("<a href='https://vabirdatlas.org/' target='_blank'>Virginia BBA</a> — Example of an interactive online atlas."))
          ),
          tags$hr(),

          h4("Breeding Bird Survey (BBS)"),
          tags$ul(
            tags$li(HTML("<a href='https://www.pwrc.usgs.gov/bbs/RouteMap/Map.cfm' target='_blank'>BBS Route Map</a> — View the location of BBS routes in your region (maps may load slowly)."))
          ),
          tags$hr(),

          h4("Partners in Flight (PIF)"),
          tags$ul(
            tags$li(HTML("<a href='https://partnersinflight.org/resources/population-estimates-database/' target='_blank'>PIF Population Estimates Database</a> — Population estimates for all landbird species breeding in the US and Canada."))
          ),
          tags$hr(),

          h4("Point Count Surveys"),
          tags$ul(
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/bird-monitoring-methods/#point-count/' target='_blank'>Point Count Survey Methods</a> — Cornell Land Trust overview of point count methodology.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/sample-bird-monitoring-protocols/' target='_blank'>Sample Point Count Protocols</a> — Example protocols for point count surveys."))
          ),
          tags$hr(),

          h4("Transect Surveys"),
          tags$ul(
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/bird-monitoring-methods/#transect-survey' target='_blank'>Transect Survey Methods</a> — Cornell Land Trust overview of line transect methodology."))
          ),
          tags$hr(),

          h4("Fixed Location Counts"),
          tags$ul(
            tags$li(HTML("<a href='https://www.hawkmigration.org/data-submission/' target='_blank'>HawkWatch International</a> — Data submission guidelines and protocols for hawk watching and fixed location count surveys."))
          ),
          tags$hr(),

          h4("Acoustic Monitoring (ARU)"),
          tags$ul(
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/bird-monitoring-methods/#acoustic-recording' target='_blank'>Acoustic Recording Methods</a> — Cornell Land Trust overview of autonomous recording unit (ARU) methodology.")),
            tags$li(HTML("<a href='https://www.birds.cornell.edu/landtrust/acoustic-monitoring/' target='_blank'>Acoustic Monitoring Tools and Resources</a> — Additional tools and resources for acoustic monitoring programs.")),
            tags$li(HTML("<a href='https://onlinelibrary.wiley.com/doi/full/10.1111/ibi.12944' target='_blank'>Perez-Granados and Traba 2021</a> — Acoustic distance sampling for estimating bird population size from ARU recordings."))
          )
        )
      )
    ),

    # Cost Comparison tab ----
    tabPanel(
      "Cost Comparison",
      sidebarLayout(
        sidebarPanel(

          wellPanel(
            tags$h4("Survey Design"),
            numericInput("num_pts", "Enter number of points:",  value = 20, min = 1,  max = 100),
            numericInput("num_yrs", "Enter number of years:",   value = 3,  min = 2,  max = 10)
          ),
          wellPanel(
            tags$h4("ARU Costs"),
            selectInput(
              "aru_select", "Select ARU type:",
              choices = c(
                "AudioMoth ($99.99)",
                "Song Meter Micro 2 ($149)",
                "Bar V2 ($320)",
                "SwiftOne ($349)",
                "Chorus ($499)",
                "Song Meter Mini 2 AA ($499)",
                "Song Meter Mini 2 Li-ion ($599)",
                "BAR-LT ($576)",
                "Solar BAR ($743)",
                "SM5 ($799)",
                "Ranger ($1,224)"
              ),
              selected = "Song Meter Mini 2 AA ($499)"
            ),
            selectInput(
              "sd_select", "Select memory card type:",
              choices = c(
                "128 GB SD card ($50)",
                "64 GB SD card ($40)",
                "128GB micro SD ($30)",
                "64GB micro SD ($20)"
              ),
              selected = "128 GB SD card ($50)"
            ),
            numericInput("aru_price",   "Price of selected ARU + memory cards ($):", value = 599, min = 0),
            numericInput("aru_install", "Annual installation/take down costs ($):",  value = 750, min = 0),
            numericInput("aru_annual",  "Annual supplies costs ($):",                value = 200, min = 0),
            numericInput("aru_process", "Annual data processing costs ($):",         value = 500, min = 0),
            numericInput("aru_storage", "Storage cost ($):",                         value = 500, min = 0),
            textOutput("storage_note"),
