)

# Server ----

server <- function(input, output, session) {

  # Tool state ----
  tool_state <- reactiveValues(
    scale    = NULL,
    question = NULL,
    metric   = NULL,
    observer = NULL,
    resource = NULL,
    clicked  = character()
  )

  # Reset ----
  observeEvent(input$reset_tool, {
    tool_state$scale    <- NULL
    tool_state$question <- NULL
    tool_state$metric   <- NULL
    tool_state$observer <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- character()
    session$sendCustomMessage("resetButtons", list())
  })

  # Breadcrumb UI ----
  output$breadcrumb_ui <- renderUI({
    if (is.null(tool_state$scale)) return(NULL)

    sep  <- tags$span("›", style = "color: #aaa; margin: 0 6px; font-size: 1.1em; line-height: 1;")
    link <- function(id, label) {
      actionLink(id, label,
        style = "color: #337ab7; font-size: 0.85em; text-decoration: none;",
        class = "breadcrumb-link"
      )
    }

    crumbs <- list(link("bc_scale", tool_state$scale))
    if (!is.null(tool_state$question))
      crumbs <- c(crumbs, list(sep, link("bc_question", tool_state$question)))
    if (!is.null(tool_state$metric))
      crumbs <- c(crumbs, list(sep, link("bc_metric", tool_state$metric)))
    if (!is.null(tool_state$observer))
      crumbs <- c(crumbs, list(sep, link("bc_observer", tool_state$observer)))

    tags$div(
      style = paste(
        "background: #f8f8f8; border: 1px solid #e0e0e0; border-radius: 4px;",
        "padding: 7px 14px; margin-bottom: 14px; display: flex;",
        "align-items: center; gap: 0; flex-wrap: wrap;"
      ),
      tags$span("Path: ", style = "color: #999; font-size: 0.82em; margin-right: 6px;"),
      do.call(tagList, crumbs)
    )
  })

  # Breadcrumb back-navigation ----
  observeEvent(input$bc_scale, {
    tool_state$scale    <- NULL
    tool_state$question <- NULL
    tool_state$metric   <- NULL
    tool_state$observer <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- character()
    session$sendCustomMessage("resetButtons", list())
  })

  observeEvent(input$bc_question, {
    tool_state$question <- NULL
    tool_state$metric   <- NULL
    tool_state$observer <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- head(tool_state$clicked, 1L)
    session$sendCustomMessage("highlightButtons", tool_state$clicked)
  })

  observeEvent(input$bc_metric, {
    tool_state$metric   <- NULL
    tool_state$observer <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- head(tool_state$clicked, 2L)
    session$sendCustomMessage("highlightButtons", tool_state$clicked)
  })

  observeEvent(input$bc_observer, {
    tool_state$observer <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- head(tool_state$clicked, 3L)
    session$sendCustomMessage("highlightButtons", tool_state$clicked)
  })

  # Step 1: Scale ----
  observeEvent(input$scale_regional, {
    if (is.null(tool_state$scale)) {
      tool_state$scale   <- "Regional"
      tool_state$clicked <- "scale_regional"
    }
  })

  observeEvent(input$scale_local, {
    if (is.null(tool_state$scale)) {
      tool_state$scale   <- "Local"
      tool_state$clicked <- "scale_local"
    }
  })

  # Step 2: Question ----
  observeEvent(input$question_effects, {
    if (!is.null(tool_state$scale) && is.null(tool_state$question)) {
      tool_state$question <- "Effects"
      tool_state$clicked  <- c(tool_state$clicked, "question_effects")
    }
  })

  observeEvent(input$question_snapshot, {
    if (!is.null(tool_state$scale) && is.null(tool_state$question)) {
      tool_state$question <- "Snapshot"
      tool_state$clicked  <- c(tool_state$clicked, "question_snapshot")
    }
  })

  observeEvent(input$question_trend, {
    if (!is.null(tool_state$scale) && is.null(tool_state$question)) {
      tool_state$question <- "Trends"
      tool_state$clicked  <- c(tool_state$clicked, "question_trend")
    }
  })

  observeEvent(input$question_process, {
    if (!is.null(tool_state$scale) && is.null(tool_state$question)) {
      tool_state$question <- "Population Size"
      tool_state$clicked  <- c(tool_state$clicked, "question_process")
    }
  })

  # Step 3: Metric ----
  local_or_regional_metric <- function() {
    isTRUE(tool_state$question %in% c("Snapshot", "Trends")) ||
      (identical(tool_state$scale, "Local") && identical(tool_state$question, "Effects"))
  }

  observeEvent(input$metric_richness, {
    if (local_or_regional_metric() && is.null(tool_state$metric)) {
      tool_state$metric  <- "Richness"
      tool_state$clicked <- c(tool_state$clicked, "metric_richness")
    }
  })

  observeEvent(input$metric_occupancy, {
    if (local_or_regional_metric() && is.null(tool_state$metric)) {
      tool_state$metric  <- "Occupancy"
      tool_state$clicked <- c(tool_state$clicked, "metric_occupancy")
    }
  })

  observeEvent(input$metric_abundance, {
    if (local_or_regional_metric() && is.null(tool_state$metric)) {
      tool_state$metric  <- "Relative Abundance"
      tool_state$clicked <- c(tool_state$clicked, "metric_abundance")
    }
  })

  observeEvent(input$metric_true_abund, {
    if (identical(tool_state$scale, "Local") && identical(tool_state$question, "Snapshot") && is.null(tool_state$metric)) {
      tool_state$metric  <- "True Abundance"
      tool_state$clicked <- c(tool_state$clicked, "metric_true_abund")
    }
  })

  # Step 4: Resource (Regional — Occupancy or Relative Abundance) ----
  observeEvent(input$resource_ebird, {
    if (identical(tool_state$scale, "Regional") &&
        isTRUE(tool_state$metric %in% c("Occupancy", "Relative Abundance")) &&
        is.null(tool_state$resource)) {
      tool_state$resource <- "eBird"
      tool_state$clicked  <- c(tool_state$clicked, "resource_ebird")
    }
  })

  observeEvent(input$resource_bba, {
    if (identical(tool_state$scale, "Regional") &&
        identical(tool_state$metric, "Occupancy") &&
        is.null(tool_state$resource)) {
      tool_state$resource <- "BBA"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bba")
    }
  })

  observeEvent(input$resource_bbs, {
    if (identical(tool_state$scale, "Regional") &&
        identical(tool_state$metric, "Relative Abundance") &&
        is.null(tool_state$resource)) {
      tool_state$resource <- "BBS"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bbs")
    }
  })

  observeEvent(input$resource_bba_pop, {
    if (identical(tool_state$question, "Population Size") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBA_Pop"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bba_pop")
    }
  })

  observeEvent(input$resource_bbs_pop, {
    if (identical(tool_state$question, "Population Size") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBS_Pop"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bbs_pop")
    }
  })

  # Step 4: Observer type (Local) ----
  observeEvent(input$observer_tech, {
    if (identical(tool_state$scale, "Local") && !is.null(tool_state$metric) && is.null(tool_state$observer)) {
      tool_state$observer <- "Technical"
      tool_state$clicked  <- c(tool_state$clicked, "observer_tech")
    }
  })

  observeEvent(input$observer_vol, {
    if (identical(tool_state$scale, "Local") && !is.null(tool_state$metric) && is.null(tool_state$observer)) {
      tool_state$observer <- "Volunteer"
      tool_state$clicked  <- c(tool_state$clicked, "observer_vol")
    }
  })

  # Shared UI block for Local true abundance / population size endpoint ----
  local_true_abund_ui <- function() {
    list(
      tags$hr(),
      p(get_txt("ep_LSP")),
      tags$div(class = "endpoint-note",
        p(tags$em("Note: True abundance estimation requires technical expertise. Volunteer-based methods are not suitable for this objective."))
      ),
      tags$h5("Recommended Methods:"),
      tags$p(HTML(get_txt("pc_LSP"))),
      tags$hr(),
      tags$p(HTML(get_txt("trans_LSP"))),
      tags$hr(),
      tags$p(HTML(get_txt("nmix_LSP"))),
      tags$hr(),
      tags$p(HTML(get_txt("aru_LSP")))
    )
  }

  # Tool UI rendering ----
  output$tool_ui <- renderUI({

    out <- list()

    # ── Step 1: Scale ────────────────────────────────────────────────────────
    out <- c(out, list(p(get_txt("t_geog_q"))))

    if (is.null(tool_state$scale)) {
      out <- c(out, list(
        make_choice_buttons(list(
          list(id = "scale_regional", label = "Regional", tooltip = get_txt("t_geog_desc_r")),
          list(id = "scale_local",    label = "Local",    tooltip = get_txt("t_geog_desc_l"))
        ))
      ))
    } else {
      out <- c(out, list(tags$b(paste("Scale:", tool_state$scale))))
    }

    # ── Regional path ─────────────────────────────────────────────────────────
    if (identical(tool_state$scale, "Regional")) {

      out <- c(out, list(tags$hr(), p(get_txt("t_question_q"))))

      if (is.null(tool_state$question)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(id = "question_effects",  label = get_txt("t_question_e"), tooltip = get_txt("t_question_e_ex")),
            list(id = "question_snapshot", label = get_txt("t_question_s"), tooltip = get_txt("t_question_s_ex")),
            list(id = "question_trend",    label = get_txt("t_question_d"), tooltip = get_txt("t_question_d_ex")),
            list(id = "question_process",  label = get_txt("t_question_p"), tooltip = get_txt("t_question_p_ex"))
          ))
        ))
      } else {
        out <- c(out, list(tags$b(paste("Question:", tool_state$question))))
      }

      # ── Effects endpoint ──────────────────────────────────────────────────
      if (identical(tool_state$question, "Effects")) {
        out <- c(out, list(
          tags$hr(),
          tags$div(class = "endpoint-note", p(get_txt("ep_RE")))
        ))
      }

      # ── Snapshot / Trends: metric step ───────────────────────────────────
      if (isTRUE(tool_state$question %in% c("Snapshot", "Trends"))) {

        out <- c(out, list(tags$hr()))

        if (identical(tool_state$question, "Snapshot")) {
          out <- c(out, list(p(get_txt("t_metric_q"))))
        } else {
          out <- c(out, list(p(get_txt("t_metric_trend_q"))))
        }

        if (is.null(tool_state$metric)) {
          if (identical(tool_state$question, "Snapshot")) {
            out <- c(out, list(
              make_choice_buttons(list(
                list(id = "metric_richness",  label = get_txt("t_metric_r"), tooltip = get_txt("t_metric_r_ex")),
                list(id = "metric_occupancy", label = get_txt("t_metric_o"), tooltip = get_txt("t_metric_o_ex")),
                list(id = "metric_abundance", label = get_txt("t_metric_a"), tooltip = get_txt("t_metric_a_ex"))
              ))
            ))
          } else {
            out <- c(out, list(
              make_choice_buttons(list(
                list(id = "metric_richness",  label = get_txt("t_metric_trend_r"), tooltip = get_txt("t_metric_trend_r_ex")),
                list(id = "metric_occupancy", label = get_txt("t_metric_trend_o"), tooltip = get_txt("t_metric_trend_o_ex")),
                list(id = "metric_abundance", label = get_txt("t_metric_trend_a"), tooltip = get_txt("t_metric_trend_a_ex"))
              ))
            ))
          }

        } else {
          out <- c(out, list(tags$b(paste("Metric:", tool_state$metric))))

          # ── Richness endpoint ───────────────────────────────────────────
          if (identical(tool_state$metric, "Richness")) {
            out <- c(out, list(tags$hr()))
            if (identical(tool_state$question, "Snapshot")) {
