          }

          # ── Occupancy endpoint ──────────────────────────────────────────
          if (identical(tool_state$metric, "Occupancy")) {
            is_trends <- identical(tool_state$question, "Trends")
            occ_intro <- if (is_trends) "ep_RTO"              else "ep_RSO"
            occ_s     <- if (is_trends) "ep_RTO_s"            else "ep_RSO_s"
            occ_s_ex  <- if (is_trends) "ep_RTO_s_ex"         else "ep_RSO_s_ex"
            occ_e     <- if (is_trends) "ep_RTO_e"            else "ep_RSO_e"
            occ_e_ex  <- if (is_trends) "ep_RTO_e_ex"         else "ep_RSO_e_ex"
            occ_b     <- if (is_trends) "ep_RTO_b"            else "ep_RSO_b"
            occ_b_ex  <- if (is_trends) "ep_RTO_b_ex"         else "ep_RSO_b_ex"
            occ_local <- if (is_trends) "ep_RTO_local"        else "ep_RSO_local"
            ebird_tag <- if (is_trends) "eBird_trend_occ"     else "eBird_occ"
            bba_tag   <- if (is_trends) "BBA_trend_occ"       else "BBA_occ"
            ebird_ex  <- if (is_trends) "eBird_trend_occ_ex"  else "eBird_occ_ex"
            bba_ex    <- if (is_trends) "BBA_trend_occ_ex"    else "BBA_occ_ex"

            out <- c(out, list(
              tags$hr(),
              p(get_txt(occ_intro)),
              tags$h5(get_txt(occ_s),   style = "text-indent: 20px;"),
              tags$em(get_txt(occ_s_ex)),
              tags$h5(get_txt(occ_e),   style = "text-indent: 20px;"),
              tags$em(get_txt(occ_e_ex)),
              tags$h5(get_txt(occ_b),   style = "text-indent: 20px;"),
              HTML(get_txt(occ_b_ex)),
              tags$div(class = "endpoint-note", p(tags$em(get_txt(occ_local))))
            ))

            if (is.null(tool_state$resource)) {
              out <- c(out, list(
                make_choice_buttons(list(
                  list(id = "resource_ebird", label = "eBird resources", tooltip = get_txt(ebird_ex)),
                  list(id = "resource_bba",   label = "BBA resources",   tooltip = get_txt(bba_ex))
                ))
              ))
            } else if (identical(tool_state$resource, "eBird")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: eBird"),
                tags$p(HTML(get_txt(ebird_tag)))
              ))
            } else if (identical(tool_state$resource, "BBA")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: BBA"),
                tags$p(HTML(get_txt(bba_tag)))
              ))
            }
          }

          # ── Relative Abundance endpoint ─────────────────────────────────
          if (identical(tool_state$metric, "Relative Abundance")) {
            is_trends_ra <- identical(tool_state$question, "Trends")
            ra_intro     <- if (is_trends_ra) "ep_RTA"               else "ep_RSA"
            ra_q1        <- if (is_trends_ra) "ep_RTA_q1"            else "ep_RSA_q1"
            ra_q1_ex     <- if (is_trends_ra) "ep_RTA_q1_ex"         else "ep_RSA_q1_ex"
            ra_q2        <- if (is_trends_ra) "ep_RTA_q2"            else "ep_RSA_q2"
            ra_q2_ex     <- if (is_trends_ra) "ep_RTA_q2_ex"         else "ep_RSA_q2_ex"
            ra_q3        <- if (is_trends_ra) "ep_RTA_q3"            else "ep_RSA_q3"
            ra_q3_ex     <- if (is_trends_ra) "ep_RTA_q3_ex"         else "ep_RSA_q3_ex"
            ebird_ra_tag <- if (is_trends_ra) "eBird_trend_abund"    else "eBird_abund"
            ebird_ra_ex  <- if (is_trends_ra) "eBird_trend_abund_ex" else "eBird_abund_ex"
            bbs_ra_tag   <- if (is_trends_ra) "BBS_trend_abund"      else "BBS_abund"
            bbs_ra_ex    <- if (is_trends_ra) "BBS_trend_abund_ex"   else "BBS_abund_ex"

            out <- c(out, list(
              tags$hr(),
              p(get_txt(ra_intro)),
              tags$h5(get_txt(ra_q1), style = "text-indent: 20px;"),
              tags$em(HTML(get_txt(ra_q1_ex))),
              tags$h5(get_txt(ra_q2), style = "text-indent: 20px;"),
              tags$em(get_txt(ra_q2_ex)),
              tags$h5(get_txt(ra_q3), style = "text-indent: 20px;"),
              tags$em(get_txt(ra_q3_ex))
            ))

            if (is.null(tool_state$resource)) {
              out <- c(out, list(
                make_choice_buttons(list(
                  list(id = "resource_ebird", label = "eBird resources", tooltip = get_txt(ebird_ra_ex)),
                  list(id = "resource_bbs",   label = "BBS resources",   tooltip = get_txt(bbs_ra_ex))
                ))
              ))
            } else if (identical(tool_state$resource, "eBird")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: eBird"),
                tags$p(HTML(get_txt(ebird_ra_tag)))
              ))
            } else if (identical(tool_state$resource, "BBS")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: BBS"),
                tags$p(HTML(get_txt(bbs_ra_tag)))
              ))
            }
          }
        }
      }

      # ── Population Size endpoint ──────────────────────────────────────────
      if (identical(tool_state$question, "Population Size")) {
        out <- c(out, list(
          tags$hr(),
          p(get_txt("ep_RPS")),
          tags$h5(get_txt("ep_RPS_bba_q"), style = "text-indent: 20px;"),
          HTML(get_txt("ep_RPS_bba_ex")),
          tags$h5(get_txt("ep_RPS_pif_q"), style = "text-indent: 20px;"),
          tags$em(get_txt("ep_RPS_pif_ex")),
          tags$div(class = "endpoint-note", p(tags$em(get_txt("ep_RPS_local"))))
        ))

        if (is.null(tool_state$resource)) {
          out <- c(out, list(
            make_choice_buttons(list(
              list(id = "resource_bba_pop", label = "BBA resources", tooltip = get_txt("BBA_pop_ex")),
              list(id = "resource_bbs_pop", label = "PIF resources", tooltip = get_txt("PIF_pop_ex"))
            ))
          ))
        } else if (identical(tool_state$resource, "BBA_Pop")) {
          out <- c(out, list(
            tags$hr(),
            tags$b("Resource: BBA"),
            tags$p(HTML(get_txt("BBA_pop")))
          ))
        } else if (identical(tool_state$resource, "BBS_Pop")) {
          out <- c(out, list(
            tags$hr(),
            tags$b("Resource: Partners in Flight"),
            tags$p(HTML(get_txt("PIF_pop")))
          ))
        }
      }
    }

    # ── Local path ────────────────────────────────────────────────────────────
    if (identical(tool_state$scale, "Local")) {

      out <- c(out, list(tags$hr(), p(get_txt("t_question_q"))))

      if (is.null(tool_state$question)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(id = "question_effects",  label = get_txt("t_question_e"), tooltip = get_txt("t_local_q_e_ex")),
            list(id = "question_snapshot", label = get_txt("t_question_s"), tooltip = get_txt("t_local_q_s_ex")),
            list(id = "question_trend",    label = get_txt("t_question_d"), tooltip = get_txt("t_local_q_d_ex")),
            list(id = "question_process",  label = get_txt("t_question_p"), tooltip = get_txt("t_question_p_ex"))
          ))
        ))
      } else {
        out <- c(out, list(tags$b(paste("Question:", tool_state$question))))

        # Population Size goes directly to the true-abundance endpoint
        if (identical(tool_state$question, "Population Size")) {
          out <- c(out, local_true_abund_ui())

        } else {

        out <- c(out, list(tags$hr(), p(get_txt("t_metric_q"))))

        if (is.null(tool_state$metric)) {
          metric_btns <- list(
            list(id = "metric_richness",  label = get_txt("t_metric_r"),    tooltip = get_txt("t_local_m_r_ex")),
            list(id = "metric_occupancy", label = get_txt("t_metric_o"),    tooltip = get_txt("t_local_m_o_ex")),
            list(id = "metric_abundance", label = get_txt("t_metric_a"),    tooltip = get_txt("t_local_m_a_ex"))
          )
          if (identical(tool_state$question, "Snapshot")) {
            metric_btns <- c(metric_btns, list(
              list(id = "metric_true_abund", label = get_txt("t_metric_l_ta"), tooltip = get_txt("t_metric_l_ta_ex"))
            ))
          }
          out <- c(out, list(make_choice_buttons(metric_btns)))

        } else {
          out <- c(out, list(tags$b(paste("Metric:", tool_state$metric))))

          # True Abundance — Technical only, no observer step
          if (identical(tool_state$metric, "True Abundance")) {
            out <- c(out, local_true_abund_ui())
          } else {

          q_key <- switch(tool_state$question, "Effects" = "E", "Snapshot" = "S", "Trends" = "T", "E")
          m_key <- switch(tool_state$metric, "Richness" = "R", "Occupancy" = "O", "Relative Abundance" = "A", "R")
          combo <- paste0(q_key, m_key)

          out <- c(out, list(
            tags$hr(),
            p(get_txt(paste0("ep_L", combo))),
            p(tags$b("What type of observers do you have?"))
          ))

          if (is.null(tool_state$observer)) {
            out <- c(out, list(
              make_choice_buttons(list(
                list(id = "observer_tech", label = "Technical observers", tooltip = get_txt("t_obs_tech_def")),
                list(id = "observer_vol",  label = "Volunteer observers", tooltip = get_txt("t_obs_vol_def"))
              ))
            ))
          } else {
            out <- c(out, list(tags$b(paste("Observer type:", tool_state$observer)), tags$hr()))

            if (identical(tool_state$observer, "Technical")) {
              out <- c(out, list(
                tags$h5("Recommended Methods:"),
                tags$p(HTML(get_txt(paste0("pc_L",    combo)))),
                tags$hr(),
                tags$p(HTML(get_txt(paste0("trans_L", combo)))),
                tags$hr(),
                tags$p(HTML(get_txt(paste0("fixed_L", combo)))),
                tags$hr(),
                tags$p(HTML(get_txt(paste0("aru_L",   combo))))
              ))
              out <- c(out, list(
                tags$hr(),
                tags$div(class = "endpoint-note", tags$em(get_txt("t_vis_aud")))
              ))
            } else {
              out <- c(out, list(
                tags$h5("Recommended Methods:"),
                tags$p(HTML(get_txt(paste0("ebird_L",  combo)))),
                tags$hr(),
                tags$p(HTML(get_txt("fixed_vol_L")))
              ))
            }
          }
          }  # end non-True Abundance branch
        }
        }  # end non-Population Size branch
      }
    }

    # Re-initialize tooltips and highlights after render
    clicked_now <- isolate(tool_state$clicked)
    session$onFlushed(function() {
      session$sendCustomMessage("initTooltips",    list())
      session$sendCustomMessage("highlightButtons", clicked_now)
    }, once = TRUE)

    do.call(tagList, out)
  })

  # Navigation ----
  observeEvent(input$go_to_tool, {
    updateNavbarPage(session, "main_navbar", selected = "Tool")
  })

  # Cost Comparison ----

  aru_prices <- c(
    "AudioMoth ($99.99)"              =   99.99,
    "Song Meter Micro 2 ($149)"       =  149,
    "Bar V2 ($320)"                   =  320,
    "SwiftOne ($349)"                 =  349,
    "Chorus ($499)"                   =  499,
    "Song Meter Mini 2 AA ($499)"     =  499,
    "Song Meter Mini 2 Li-ion ($599)" =  599,
    "BAR-LT ($576)"                   =  576,
    "Solar BAR ($743)"                =  743,
    "SM5 ($799)"                      =  799,
    "Ranger ($1,224)"                 = 1224
  )

  memory_prices <- c(
    "128 GB SD card ($50)" = 50,
    "64 GB SD card ($40)"  = 40,
    "128GB micro SD ($30)" = 30,
    "64GB micro SD ($20)"  = 20
  )

  observeEvent(list(input$aru_select, input$sd_select), {
    total <- aru_prices[[input$aru_select]] + memory_prices[[input$sd_select]] * 2L
    updateNumericInput(session, "aru_price", value = total)
  })

  output$storage_note <- renderText({
    if (input$storage_onetime) {
      "Storage cost is being treated as a one-time purchase."
    } else {
      "Storage cost is being treated as a recurring annual expense."
    }
  })

  # Shared cost calculation (avoids duplication between summary and plot)
  cost_data <- reactive({
    x               <- seq_len(input$num_yrs)
    storage_onetime <- input$storage_onetime
    storage_cost    <- input$aru_storage
    aru_upfront     <- input$aru_price * input$num_pts +
                       if (storage_onetime) storage_cost else 0
    aru_annual_cost <- input$aru_install + input$aru_annual + input$aru_process +
                       if (!storage_onetime) storage_cost else 0
    list(
      x                = x,
      point_count_cost = x * input$ptc_cost,
      aru_total_cost   = aru_upfront + x * aru_annual_cost
    )
  })

  output$breakeven_ui <- renderUI({
    d     <- cost_data()
    cross <- which(diff(sign(d$aru_total_cost - d$point_count_cost)) != 0)

    msg <- if (length(cross) > 0) {
      k <- cross[1]
      bx <- k + (d$aru_total_cost - d$point_count_cost)[k] /
                ((d$aru_total_cost - d$point_count_cost)[k] - (d$aru_total_cost - d$point_count_cost)[k + 1])
      paste0("At these inputs, ARUs become cost-effective compared to point counts after approximately ", round(bx, 1), " years.")
    } else if (all(d$aru_total_cost <= d$point_count_cost)) {
      "At these inputs, ARUs are less expensive than point counts from year one."
    } else {
      paste0("At these inputs, ARUs do not break even with point counts within the ",
             input$num_yrs, "-year window.")
    }

    tags$div(
      style = paste("background:#f0f7ff; border-left:3px solid #5b9bd5;",
                    "padding:8px 14px; margin-bottom:12px; font-size:0.9em;"),
      tags$em(msg)
    )
  })

  output$graph <- renderPlot({
    d <- cost_data()

    y_min <- min(d$point_count_cost, d$aru_total_cost)
    y_max <- max(d$point_count_cost, d$aru_total_cost)

    plot(
      d$x, d$point_count_cost,
      type = "l", col = "steelblue", lwd = 3,
      xlab = "Years", ylab = "Cumulative cost (USD)",
      ylim = c(y_min, y_max),
      main = "Cumulative Cost of Monitoring Over Time",
      cex.lab = 1.2, cex.axis = 1.1,
      xaxt = "n"
    )
    axis(1, at = d$x)
    lines(d$x, d$aru_total_cost, col = "darkorange", lwd = 3)

    cross <- which(diff(sign(d$aru_total_cost - d$point_count_cost)) != 0)
    if (length(cross) > 0) {
      k  <- cross[1]
      bx <- k + (d$aru_total_cost - d$point_count_cost)[k] /
                ((d$aru_total_cost - d$point_count_cost)[k] - (d$aru_total_cost - d$point_count_cost)[k + 1])
      abline(v = bx, lty = 2, col = "gray50")
      mtext("breakeven", side = 3, at = bx, cex = 0.85, col = "gray40")
    }

    legend(
      "topleft",
      legend = c("Point Count", "ARU"),
      col    = c("steelblue", "darkorange"),
      lwd    = 3, bty = "n", cex = 1.2
    )
  })
}

# Run ----
shinyApp(ui = ui, server = server)

