# Define server logic for the application
server <- function(input, output, session) {
  
  # Reactive value to store the current text
  dynamicContent <- reactiveVal(list())  # Initialize with an empty list of tags
  
  # Reset dynamic content
  observeEvent(input$reset_tool, {
    dynamicContent(list())  # Clears UI
    clicked_buttons(character())  # Clears tracked buttons
    session$sendCustomMessage(type = 'resetButtons', message = list())  # Clears visual class
  })
  
  #Track clicked buttons
  clicked_buttons <- reactiveVal(character())
  
  # Update text based on button clicks
  observeEvent(input$btn1, {
    clicked_buttons(c(clicked_buttons(), "btn1"))
    current <- dynamicContent()
    newContent <- list(
      tags$b("Scale: Regional"),
      tags$p(tooltxt$Text[tooltxt$TextTag == "t_question_q"]),
      tags$div(
        fluidRow(
          lapply(
            list(
              list(id = "btn3", tag = "t_question_e", ex_tag = "t_question_e_ex"),
              list(id = "btn4", tag = "t_question_s", ex_tag = "t_question_s_ex"),
              list(id = "btn5", tag = "t_question_d", ex_tag = "t_question_d_ex"),
              list(id = "btn6", tag = "t_question_p", ex_tag = "t_question_p_ex")
            ),
            function(btn) {
              div(
                class = "col-12 col-md-6",  # full width on small screens, 50% width on medium+
                actionButton(
                  inputId = btn$id,
                  label = tooltxt$Text[tooltxt$TextTag == btn$tag],
                  style = "
            white-space: normal;
            height: auto;
            width: 100%;
            margin-bottom: 10px;",
                  `data-toggle` = "tooltip",
                  title = tooltxt$Text[tooltxt$TextTag == btn$ex_tag]
                )
              )
            }
          )
        )
      )
    )
    dynamicContent(c(current, newContent))  #Append new content
  })
  
  # Update content when "Effects" is clicked
  observeEvent(input$btn3, {
    updated_clicks <- unique(c(clicked_buttons(), "btn3"))
    clicked_buttons(updated_clicks)  # Save it reactively
    current <- dynamicContent()  # Get the current content
    newContent <- list(
      tags$b("Question: Effects")#,
      #tags$p(tooltxt$Text[tooltxt$TextTag == "effects_description"], style = "text-indent: 20px;")
    )
    dynamicContent(c(current, newContent))  # Append new content
    session$onFlushed(function() {
      session$sendCustomMessage(type = 'highlightButtons', message = updated_clicks)
      session$sendCustomMessage(type = 'initTooltips', message = list())
    }, once = TRUE)
  })
  
