# Server ----

server <- function(input, output, session) {
  
  # Tool state ----
  tool_state <- reactiveValues(
    scale = NULL,
    question = NULL,
    metric = NULL,
    resource = NULL,
    clicked = character()
  )
  
  # Tool reset ----
  observeEvent(input$reset_tool, {
    tool_state$scale <- NULL
    tool_state$question <- NULL
    tool_state$metric <- NULL
    tool_state$resource <- NULL
    tool_state$clicked <- character()
    
    session$sendCustomMessage("resetButtons", list())
  })
  
  # Tool observers: step 1 (scale) ----
  observeEvent(input$scale_regional, {
    if (is.null(tool_state$scale)) {
      tool_state$scale <- "Regional"
      tool_state$clicked <- c("scale_regional")
    }
  })
  
  observeEvent(input$scale_local, {
    if (is.null(tool_state$scale)) {
      tool_state$scale <- "Local"
      tool_state$clicked <- c("scale_local")
    }
  })
  
  ## Tool observers: Regional: step 2 (question) ----
  observeEvent(input$question_effects, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Effects"
      tool_state$clicked <- c(tool_state$clicked, "question_effects")
    }
  })
  
  observeEvent(input$question_snapshot, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Snapshot"
      tool_state$clicked <- c(tool_state$clicked, "question_snapshot")
    }
  })
  
  observeEvent(input$question_trend, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Trends"
      tool_state$clicked <- c(tool_state$clicked, "question_trend")
    }
  })
  
  observeEvent(input$question_process, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Population Size"
      tool_state$clicked <- c(tool_state$clicked, "question_process")
    }
  })
  
  ### Tool observers: Snapshot: step 3 (metric) ----
  observeEvent(input$metric_richness, {
    if (identical(tool_state$question, "Snapshot") && is.null(tool_state$metric)) {
      tool_state$metric <- "Richness"
      tool_state$clicked <- c(tool_state$clicked, "metric_richness")
    }
  })
  
  observeEvent(input$metric_occupancy, {
    if (identical(tool_state$question, "Snapshot") && is.null(tool_state$metric)) {
      tool_state$metric <- "Occupancy"
      tool_state$clicked <- c(tool_state$clicked, "metric_occupancy")
    }
  })
  
  observeEvent(input$metric_abundance, {
    if (identical(tool_state$question, "Snapshot") && is.null(tool_state$metric)) {
      tool_state$metric <- "Relative Abundance"
      tool_state$clicked <- c(tool_state$clicked, "metric_abundance")
    }
  })
  
  #### Tool observers: Occupancy: step 4 (resource) ----
  observeEvent(input$resource_ebird, {
    if (identical(tool_state$metric, "Occupancy") && is.null(tool_state$resource)) {
      tool_state$resource <- "eBird"
      tool_state$clicked <- c(tool_state$clicked, "resource_ebird")
    }
  })
  
  observeEvent(input$resource_bba, {
    if (identical(tool_state$metric, "Occupancy") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBA"
      tool_state$clicked <- c(tool_state$clicked, "resource_bba")
    }
  })
  
  # Tool UI rendering ----
  output$tool_ui <- renderUI({
    
    out <- list()
    
    # Step 1: scale ----
    out <- c(out, list(
      p(get_txt("t_geog_q"))
    ))
    
    if (is.null(tool_state$scale)) {
      out <- c(out, list(
        make_choice_buttons(list(
          list(
            id = "scale_regional",
            label = "Regional",
            tooltip = get_txt("t_geog_desc_r")
          ),
          list(
            id = "scale_local",
            label = "Local",
            tooltip = get_txt("t_geog_desc_l")
          )
        ))
      ))
    } else {
      out <- c(out, list(
        tags$b(paste("Scale:", tool_state$scale))
      ))
    }
    
    # Regional path ----
    if (identical(tool_state$scale, "Regional")) {
      
      out <- c(out, list(tags$hr()))
      out <- c(out, list(
        p(get_txt("t_question_q"))
      ))
      
      if (is.null(tool_state$question)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(
              id = "question_effects",
              label = get_txt("t_question_e"),
              tooltip = get_txt("t_question_e_ex")
            ),
            list(
              id = "question_snapshot",
              label = get_txt("t_question_s"),
              tooltip = get_txt("t_question_s_ex")
            ),
            list(
              id = "question_trend",
              label = get_txt("t_question_d"),
              tooltip = get_txt("t_question_d_ex")
            ),
            list(
              id = "question_process",
              label = get_txt("t_question_p"),
              tooltip = get_txt("t_question_p_ex")
            )
          ))
        ))
      } else {
        out <- c(out, list(
          tags$b(paste("Question:", tool_state$question))
        ))
      }
    }
    
    ## Regional: Snapshot path ----
    if (identical(tool_state$question, "Snapshot")) {
      
      out <- c(out, list(tags$hr()))
      out <- c(out, list(
        p(get_txt("t_metric_q"))
      ))
      
      if (is.null(tool_state$metric)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(
              id = "metric_richness",
              label = get_txt("t_metric_r"),
              tooltip = get_txt("t_metric_r_ex")
            ),
            list(
              id = "metric_occupancy",
              label = get_txt("t_metric_o"),
              tooltip = get_txt("t_metric_o_ex")
            ),
            list(
              id = "metric_abundance",
              label = get_txt("t_metric_a"),
              tooltip = get_txt("t_metric_a_ex")
            )
          ))
        ))
      } else {
        out <- c(out, list(
          tags$b(paste("Metric:", tool_state$metric))
        ))
      }
    }
    
    ### Regional:Snapshot:Occupancy output ----
    if (identical(tool_state$metric, "Occupancy")) {
      
      out <- c(out, list(tags$hr()))
      out <- c(out, list(
        p(get_txt("ep_RSO")),
        tags$h5(get_txt("ep_RSO_s"), style = "text-indent: 20px;"),
        tags$em(get_txt("ep_RSO_s_ex")),
        tags$h5(get_txt("ep_RSO_e"), style = "text-indent: 20px;"),
        tags$em(get_txt("ep_RSO_e_ex")),
        tags$h5(get_txt("ep_RSO_b"), style = "text-indent: 20px;"),
        tags$em(get_txt("ep_RSO_b_ex"))
      ))
      
      if (is.null(tool_state$resource)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(
              id = "resource_ebird",
              label = "eBird resources",
              tooltip = get_txt("eBird_occ_ex")
            ),
            list(
              id = "resource_bba",
              label = "BBA resources",
              tooltip = get_txt("BBA_occ_ex")
            )
          ))
        ))
      } else if (identical(tool_state$resource, "eBird")) {
        out <- c(out, list(
          tags$hr(),
          tags$b("Resource: eBird"),
          tags$p(HTML(get_txt("eBird_occ")))
        ))
      } else if (identical(tool_state$resource, "BBA")) {
        out <- c(out, list(
          tags$hr(),
          tags$b("Resource: BBA"),
          tags$p(HTML(get_txt("BBA_occ")))
        ))
      }
    }
    
    # Local path placeholder ----
    if (identical(tool_state$scale, "Local")) {
      out <- c(out, list(
        tags$hr(),
        tags$b("Scale: Local"),
        p("Local pathway not yet built.")
      ))
    }
    
    # Capture reactive value now, then use plain value later
    clicked_now <- isolate(tool_state$clicked)
    
    session$onFlushed(function() {
      session$sendCustomMessage("initTooltips", list())
      session$sendCustomMessage("highlightButtons", clicked_now)
    }, once = TRUE)
    
    do.call(tagList, out)
  })
  
  # Navigation ----
  observeEvent(input$go_to_tool, {
    updateNavbarPage(session, "main_navbar", selected = "Tool")
  })
  
  # Cost comparison logic ----
  aru_prices <- list(
    "WA Song Meter SM4 ($699)" = 699,
    "WA Song Meter Mini 2AA ($499)" = 499,
    "WA Song Meter Micro 2 ($149)" = 149,
    "Audiomoth ($99)" = 99
  )
  
  memory_prices <- list(
    "128 GB SD card ($15)" = 15,
    "64 GB SD card ($10)" = 10,
    "128GB micro SD ($10)" = 10,
    "64GB micro SD ($7)" = 7
  )
  
  observeEvent(
    {
      input$aru_select
      input$sd_select
    },
    {
      aru_val <- aru_prices[[input$aru_select]]
      mem_val <- memory_prices[[input$sd_select]]
      total_val <- aru_val + mem_val * 2
      updateNumericInput(session, "aru_price", value = total_val)
    }
  )
  
  output$storage_note <- renderText({
    if (input$storage_onetime) {
      "Storage cost is being treated as a one-time purchase."
    } else {
      "Storage cost is being treated as a recurring annual expense."
    }
  })
  
  output$graph <- renderPlot({
    input$plot
    
    isolate({
      x <- 1:input$num_yrs
      
      storage_onetime <- input$storage_onetime
      storage_cost <- input$aru_storage
      
      aru_cost <- input$aru_price + if (storage_onetime) storage_cost else 0
      aru_annual_cost <- input$aru_install +
        input$aru_annual +
        (if (!storage_onetime) storage_cost else 0) +
        input$aru_process
      
      point_count_cost <- x * input$ptc_cost
      aru_total_cost <- aru_cost * input$num_pts + x * aru_annual_cost
      
      y <- rbind(point_count_cost, aru_total_cost)
      
      plot(
        x, y[1, ],
        type = "l",
        col = "lightblue",
        lwd = 4,
        xlab = "Years",
        ylab = "Cost in $",
        ylim = c(min(y), max(y)),
        main = "Cost of Monitoring over Time",
        cex = 1.2
      )
      
      lines(x, y[2, ], col = "orange", lwd = 4)
      
      legend(
        "bottomright",
        legend = c("Point Count", "ARU"),
        fill = c("lightblue", "orange"),
        bty = "n",
        cex = 1.2
      )
    })
  })
}

