get_txt <- function(tag) {
  x <- tooltxt$Text[tooltxt$TextTag == tag]
  if (length(x) == 0) "" else x[1]
}

# Build a row of equal-width buttons (auto-sizes columns to fit count)
make_choice_buttons <- function(button_info) {
  n <- length(button_info)
  col_width <- max(3L, 12L %/% n)
  fluidRow(
    lapply(button_info, function(btn) {
      column(
        width = col_width,
        actionButton(
          inputId  = btn$id,
          label    = btn$label,
          style    = "white-space: normal; height: auto; width: 100%; margin-bottom: 10px;",
          `data-toggle` = "tooltip",
          title    = btn$tooltip
        )
      )
    })
  )
}

