# Server ----

server <- function(input, output, session) {

  # Tool state ----
  tool_state <- reactiveValues(
    scale    = NULL,
    question = NULL,
    metric   = NULL,
    resource = NULL,
    clicked  = character()
  )

  # Reset ----
  observeEvent(input$reset_tool, {
    tool_state$scale    <- NULL
    tool_state$question <- NULL
    tool_state$metric   <- NULL
    tool_state$resource <- NULL
    tool_state$clicked  <- character()
    session$sendCustomMessage("resetButtons", list())
  })

  # Step 1: Scale ----
  observeEvent(input$scale_regional, {
    if (is.null(tool_state$scale)) {
      tool_state$scale   <- "Regional"
      tool_state$clicked <- "scale_regional"
    }
  })

  observeEvent(input$scale_local, {
    if (is.null(tool_state$scale)) {
      tool_state$scale   <- "Local"
      tool_state$clicked <- "scale_local"
    }
  })

  # Step 2: Question (Regional) ----
  observeEvent(input$question_effects, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Effects"
      tool_state$clicked  <- c(tool_state$clicked, "question_effects")
    }
  })

  observeEvent(input$question_snapshot, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Snapshot"
      tool_state$clicked  <- c(tool_state$clicked, "question_snapshot")
    }
  })

  observeEvent(input$question_trend, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Trends"
      tool_state$clicked  <- c(tool_state$clicked, "question_trend")
    }
  })

  observeEvent(input$question_process, {
    if (identical(tool_state$scale, "Regional") && is.null(tool_state$question)) {
      tool_state$question <- "Population Size"
      tool_state$clicked  <- c(tool_state$clicked, "question_process")
    }
  })

  # Step 3: Metric (Snapshot or Trends) ----
  observeEvent(input$metric_richness, {
    if (isTRUE(tool_state$question %in% c("Snapshot", "Trends")) && is.null(tool_state$metric)) {
      tool_state$metric  <- "Richness"
      tool_state$clicked <- c(tool_state$clicked, "metric_richness")
    }
  })

  observeEvent(input$metric_occupancy, {
    if (isTRUE(tool_state$question %in% c("Snapshot", "Trends")) && is.null(tool_state$metric)) {
      tool_state$metric  <- "Occupancy"
      tool_state$clicked <- c(tool_state$clicked, "metric_occupancy")
    }
  })

  observeEvent(input$metric_abundance, {
    if (isTRUE(tool_state$question %in% c("Snapshot", "Trends")) && is.null(tool_state$metric)) {
      tool_state$metric  <- "Relative Abundance"
      tool_state$clicked <- c(tool_state$clicked, "metric_abundance")
    }
  })

  # Step 4: Resource (Occupancy path — eBird or BBA) ----
  observeEvent(input$resource_ebird, {
    if (isTRUE(tool_state$metric %in% c("Occupancy", "Relative Abundance")) && is.null(tool_state$resource)) {
      tool_state$resource <- "eBird"
      tool_state$clicked  <- c(tool_state$clicked, "resource_ebird")
    }
  })

  observeEvent(input$resource_bba, {
    if (identical(tool_state$metric, "Occupancy") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBA"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bba")
    }
  })

  # Step 4: Resource (Relative Abundance path — BBS) ----
  observeEvent(input$resource_bbs, {
    if (identical(tool_state$metric, "Relative Abundance") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBS"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bbs")
    }
  })

  # Step 3: Resource (Population Size path — BBA or BBS/PIF) ----
  observeEvent(input$resource_bba_pop, {
    if (identical(tool_state$question, "Population Size") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBA_Pop"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bba_pop")
    }
  })

  observeEvent(input$resource_bbs_pop, {
    if (identical(tool_state$question, "Population Size") && is.null(tool_state$resource)) {
      tool_state$resource <- "BBS_Pop"
      tool_state$clicked  <- c(tool_state$clicked, "resource_bbs_pop")
    }
  })

  # Tool UI rendering ----
  output$tool_ui <- renderUI({

    out <- list()

    # ── Step 1: Scale ──────────────────────────────────────────────────────────
    out <- c(out, list(p(get_txt("t_geog_q"))))

    if (is.null(tool_state$scale)) {
      out <- c(out, list(
        make_choice_buttons(list(
          list(id = "scale_regional", label = "Regional", tooltip = get_txt("t_geog_desc_r")),
          list(id = "scale_local",    label = "Local",    tooltip = get_txt("t_geog_desc_l"))
        ))
      ))
    } else {
      out <- c(out, list(tags$b(paste("Scale:", tool_state$scale))))
    }

    # ── Regional path ──────────────────────────────────────────────────────────
    if (identical(tool_state$scale, "Regional")) {

      out <- c(out, list(tags$hr(), p(get_txt("t_question_q"))))

      if (is.null(tool_state$question)) {
        out <- c(out, list(
          make_choice_buttons(list(
            list(id = "question_effects",  label = get_txt("t_question_e"), tooltip = get_txt("t_question_e_ex")),
            list(id = "question_snapshot", label = get_txt("t_question_s"), tooltip = get_txt("t_question_s_ex")),
            list(id = "question_trend",    label = get_txt("t_question_d"), tooltip = get_txt("t_question_d_ex")),
            list(id = "question_process",  label = get_txt("t_question_p"), tooltip = get_txt("t_question_p_ex"))
          ))
        ))
      } else {
        out <- c(out, list(tags$b(paste("Question:", tool_state$question))))
      }

      # ── Effects endpoint ────────────────────────────────────────────────────
      if (identical(tool_state$question, "Effects")) {
        out <- c(out, list(
          tags$hr(),
          tags$div(class = "endpoint-note", p(get_txt("ep_RE")))
        ))
      }

      # ── Snapshot / Trends: metric step ─────────────────────────────────────
      if (isTRUE(tool_state$question %in% c("Snapshot", "Trends"))) {

        out <- c(out, list(tags$hr()))

        if (identical(tool_state$question, "Snapshot")) {
          out <- c(out, list(p(get_txt("t_metric_q"))))
        } else {
          out <- c(out, list(p(get_txt("t_metric_trend_q"))))
        }

        if (is.null(tool_state$metric)) {
          if (identical(tool_state$question, "Snapshot")) {
            out <- c(out, list(
              make_choice_buttons(list(
                list(id = "metric_richness",  label = get_txt("t_metric_r"), tooltip = get_txt("t_metric_r_ex")),
                list(id = "metric_occupancy", label = get_txt("t_metric_o"), tooltip = get_txt("t_metric_o_ex")),
                list(id = "metric_abundance", label = get_txt("t_metric_a"), tooltip = get_txt("t_metric_a_ex"))
              ))
            ))
          } else {
            out <- c(out, list(
              make_choice_buttons(list(
                list(id = "metric_richness",  label = get_txt("t_metric_trend_r"), tooltip = get_txt("t_metric_r_ex")),
                list(id = "metric_occupancy", label = get_txt("t_metric_trend_o"), tooltip = get_txt("t_metric_o_ex")),
                list(id = "metric_abundance", label = get_txt("t_metric_trend_a"), tooltip = get_txt("t_metric_a_ex"))
              ))
            ))
          }

        } else {
          out <- c(out, list(tags$b(paste("Metric:", tool_state$metric))))

          # ── Richness endpoint ─────────────────────────────────────────────
          if (identical(tool_state$metric, "Richness")) {
            out <- c(out, list(tags$hr()))
            if (identical(tool_state$question, "Snapshot")) {
              out <- c(out, list(
                p(get_txt("ep_RSR")),
                tags$div(class = "endpoint-note", p(get_txt("ep_RSR_clarify"))),
                tags$hr(),
                tags$b("Resource: eBird Status and Trends"),
                tags$p(HTML(get_txt("eBird_rich")))
              ))
            } else {
              out <- c(out, list(
                tags$p(HTML(get_txt("ep_RTR")))
              ))
            }
          }

          # ── Occupancy endpoint ────────────────────────────────────────────
          if (identical(tool_state$metric, "Occupancy")) {
            out <- c(out, list(
              tags$hr(),
              p(get_txt("ep_RSO")),
              tags$h5(get_txt("ep_RSO_s"), style = "text-indent: 20px;"),
              tags$em(get_txt("ep_RSO_s_ex")),
              tags$h5(get_txt("ep_RSO_e"), style = "text-indent: 20px;"),
              tags$em(get_txt("ep_RSO_e_ex")),
              tags$h5(get_txt("ep_RSO_b"), style = "text-indent: 20px;"),
              tags$em(get_txt("ep_RSO_b_ex")),
              tags$div(class = "endpoint-note", p(tags$em(get_txt("ep_RSO_local"))))
            ))

            if (is.null(tool_state$resource)) {
              out <- c(out, list(
                make_choice_buttons(list(
                  list(id = "resource_ebird", label = "eBird resources", tooltip = get_txt("eBird_occ_ex")),
                  list(id = "resource_bba",   label = "BBA resources",   tooltip = get_txt("BBA_occ_ex"))
                ))
              ))
            } else if (identical(tool_state$resource, "eBird")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: eBird"),
                tags$p(HTML(get_txt("eBird_occ")))
              ))
            } else if (identical(tool_state$resource, "BBA")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: BBA"),
                tags$p(HTML(get_txt("BBA_occ")))
              ))
            }
          }

          # ── Relative Abundance endpoint ───────────────────────────────────
          if (identical(tool_state$metric, "Relative Abundance")) {
            out <- c(out, list(
              tags$hr(),
              p(get_txt("ep_RSA")),
              tags$h5(get_txt("ep_RSA_q1"), style = "text-indent: 20px;"),
              tags$em(HTML(get_txt("ep_RSA_q1_ex"))),
              tags$h5(get_txt("ep_RSA_q2"), style = "text-indent: 20px;"),
              tags$em(get_txt("ep_RSA_q2_ex")),
              tags$h5(get_txt("ep_RSA_q3"), style = "text-indent: 20px;"),
              tags$em(get_txt("ep_RSA_q3_ex"))
            ))

            if (is.null(tool_state$resource)) {
              out <- c(out, list(
                make_choice_buttons(list(
                  list(id = "resource_ebird", label = "eBird resources", tooltip = get_txt("eBird_abund_ex")),
                  list(id = "resource_bbs",   label = "BBS resources",   tooltip = get_txt("BBS_abund_ex"))
                ))
              ))
            } else if (identical(tool_state$resource, "eBird")) {
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: eBird"),
                tags$p(HTML(get_txt("eBird_abund")))
              ))
            } else if (identical(tool_state$resource, "BBS")) {
              bbs_tag <- if (identical(tool_state$question, "Trends")) "BBS_trend_abund" else "BBS_abund"
              out <- c(out, list(
                tags$hr(),
                tags$b("Resource: BBS"),
                tags$p(HTML(get_txt(bbs_tag)))
              ))
            }
          }
        }
      }

      # ── Population Size endpoint ────────────────────────────────────────────
      if (identical(tool_state$question, "Population Size")) {
        out <- c(out, list(
          tags$hr(),
          p(get_txt("ep_RPS"))
        ))

        if (is.null(tool_state$resource)) {
          out <- c(out, list(
            make_choice_buttons(list(
              list(id = "resource_bba_pop", label = "BBA resources",      tooltip = get_txt("BBA_pop_ex")),
              list(id = "resource_bbs_pop", label = "BBS/PIF resources",  tooltip = get_txt("BBS_pop_ex"))
            ))
          ))
        } else if (identical(tool_state$resource, "BBA_Pop")) {
          out <- c(out, list(
            tags$hr(),
            tags$b("Resource: BBA"),
            tags$p(HTML(get_txt("BBA_pop")))
          ))
        } else if (identical(tool_state$resource, "BBS_Pop")) {
          out <- c(out, list(
            tags$hr(),
            tags$b("Resource: BBS / Partners in Flight"),
            tags$p(HTML(get_txt("BBS_pop")))
          ))
        }
      }
    }

    # ── Local path placeholder ──────────────────────────────────────────────────
    if (identical(tool_state$scale, "Local")) {
      out <- c(out, list(
        tags$hr(),
        p("The Local pathway is not yet built. Please check back later.")
      ))
    }

    # Re-initialize tooltips and highlights after render
    clicked_now <- isolate(tool_state$clicked)
    session$onFlushed(function() {
      session$sendCustomMessage("initTooltips",    list())
      session$sendCustomMessage("highlightButtons", clicked_now)
    }, once = TRUE)

    do.call(tagList, out)
  })

  # Navigation ----
  observeEvent(input$go_to_tool, {
    updateNavbarPage(session, "main_navbar", selected = "Tool")
  })

  # Cost Comparison ----

  aru_prices <- c(
    "WA Song Meter SM4 ($699)"       = 699,
    "WA Song Meter Mini 2AA ($499)"  = 499,
    "WA Song Meter Micro 2 ($149)"   = 149,
    "Audiomoth ($99)"                = 99
  )

  memory_prices <- c(
    "128 GB SD card ($15)"  = 15,
    "64 GB SD card ($10)"   = 10,
    "128GB micro SD ($10)"  = 10,
    "64GB micro SD ($7)"    = 7
  )

  observeEvent(list(input$aru_select, input$sd_select), {
    total <- aru_prices[[input$aru_select]] + memory_prices[[input$sd_select]] * 2L
    updateNumericInput(session, "aru_price", value = total)
  })

  output$storage_note <- renderText({
    if (input$storage_onetime) {
      "Storage cost is being treated as a one-time purchase."
    } else {
      "Storage cost is being treated as a recurring annual expense."
    }
  })

  output$graph <- renderPlot({
    input$plot
    isolate({
      x <- seq_len(input$num_yrs)

      storage_onetime <- input$storage_onetime
      storage_cost    <- input$aru_storage

      aru_upfront      <- input$aru_price * input$num_pts +
                          if (storage_onetime) storage_cost else 0
      aru_annual_cost  <- input$aru_install + input$aru_annual + input$aru_process +
                          if (!storage_onetime) storage_cost else 0

      point_count_cost <- x * input$ptc_cost
      aru_total_cost   <- aru_upfront + x * aru_annual_cost

      y_min <- min(point_count_cost, aru_total_cost)
      y_max <- max(point_count_cost, aru_total_cost)

      plot(
        x, point_count_cost,
        type = "l", col = "steelblue", lwd = 3,
        xlab = "Years", ylab = "Cumulative cost (USD)",
        ylim = c(y_min, y_max),
        main = "Cumulative Cost of Monitoring Over Time",
        cex.lab = 1.2, cex.axis = 1.1,
        xaxt = "n"
      )
      axis(1, at = x)
      lines(x, aru_total_cost, col = "darkorange", lwd = 3)

      # Mark breakeven year if the lines cross
      cross <- which(diff(sign(aru_total_cost - point_count_cost)) != 0)
      if (length(cross) > 0) {
        abline(v = cross[1] + 0.5, lty = 2, col = "gray50")
        mtext("breakeven", side = 3, at = cross[1] + 0.5, cex = 0.85, col = "gray40")
      }

      legend(
        "topleft",
        legend = c("Point Count", "ARU"),
        col    = c("steelblue", "darkorange"),
        lwd    = 3, bty = "n", cex = 1.2
      )
    })
  })
}

# Run ----
shinyApp(ui = ui, server = server)
